// Assuming l_int32 is a 32-bit integer type, typically a typedef for int32_t
typedef int l_int32;

// Mock function declarations assumed to exist in the same codebase
l_int32 lept_mkdir(const char *path);
l_int32 getFilenamesInDirectory(const char *dirin, char ***filelist);
l_int32 generateThumbnail(const char *input, const char *output, l_int32 width);
l_int32 generateViewableImage(const char *input, const char *output, l_int32 width);
void lepton_free(void *ptr);

l_int32 generateImageViewer(const char *dirin, const char *dirout, const char *rootname, l_int32 thumbwidth, l_int32 viewwidth) {
    // Validate input
    if (!dirin || !dirout || !rootname || thumbwidth <= 0 || viewwidth <= 0) {
        return -1;
    }

    // Create output directory if it doesn't exist
    if (lept_mkdir(dirout) != 0 && access(dirout, F_OK) != 0) {
        return -2;
    }

    // Get list of image files in input directory
    char **filelist = NULL;
    l_int32 count = getFilenamesInDirectory(dirin, &filelist);
    if (count <= 0 || !filelist) {
        return -3;
    }

    // Prepare paths for HTML files
    char mainhtml[1024];
    char linkhtml[1024];
    snprintf(mainhtml, sizeof(mainhtml), "%s/%s.html", dirout, rootname);
    snprintf(linkhtml, sizeof(linkhtml), "%s/%s_links.html", dirout, rootname);

    // Generate HTML files
    FILE *mainfp = fopen(mainhtml, "w");
    FILE *linkfp = fopen(linkhtml, "w");
    if (!mainfp || !linkfp) {
        lepton_free(filelist);
        return -4;
    }

    // Write HTML headers
    fprintf(mainfp, "<html><body><h1>Image Viewer</h1>\n");
    fprintf(linkfp, "<html><body><h1>Image Links</h1>\n");

    for (l_int32 i = 0; i < count; i++) {
        char *filename = filelist[i];
        char *base = strdup(filename);
        char thumbpath[1024];
        char viewpath[1024];
        char linkpath[1024];

        char *dot = strrchr(base, '.');
        if (dot) {
            *dot = '\0';
        }

        snprintf(thumbpath, sizeof(thumbpath), "%s/%s_thumb.jpg", dirout, base);
        snprintf(viewpath, sizeof(viewpath), "%s/%s_view.jpg", dirout, base);
        snprintf(linkpath, sizeof(linkpath), "%s.html", base);

        // Generate thumbnail and viewable image
        if (generateThumbnail(dirin, thumbpath, thumbwidth) != 0 ||
            generateViewableImage(dirin, viewpath, viewwidth) != 0) {
            fclose(mainfp);
            fclose(linkfp);
            lepton_free(filelist);
            lepton_free(base);
            return -5;
        }

        // Write entries to HTML files
        fprintf(mainfp,
                "<a href='%s'><img src='%s' alt='%s' width='%d'/></a>\n",
                linkpath, thumbpath, filename, thumbwidth);

        fprintf(linkfp,
                "<a href='%s'>%s</a><br>\n",
                linkpath, filename);
    }

    // Write HTML footers
    fprintf(mainfp, "</body></html>\n");
    fprintf(linkfp, "</body></html>\n");

    // Clean up
    fclose(mainfp);
    fclose(linkfp);
    lepton_free(filelist);
    lepton_free(base);

    return 0;
}

