l_int32 generateHtmlImageIndex(const char *dirin, const char *dirout, const char *rootname, l_int32 thumbwidth, l_int32 viewwidth) {
    // Validate input parameters
    if (!dirin || !dirout || !rootname) {
        fprintf(stderr, "Input parameters are invalid.\n");
        return 1;
    }

    // Check if input directory exists and is readable
    struct stat info;
    if (stat(dirin, &info) != 0 || !S_ISDIR(info.st_mode)) {
        fprintf(stderr, "Input directory '%s' does not exist or is not a directory.\n", dirin);
        return 1;
    }

    // Create output directory if it does not exist
    if (stat(dirout, &info) != 0 || !S_ISDIR(info.st_mode)) {
        if (mkdir(dirout, 0755) != 0) {
            fprintf(stderr, "Failed to create output directory '%s'.\n", dirout);
            return 1;
        }
    }

    // Open input directory and read image filenames
    DIR *d;
    struct dirent *entry;
    char **filenames = NULL;
    l_int32 nfiles = 0, i;

    d = opendir(dirin);
    if (!d) {
        fprintf(stderr, "Failed to open input directory '%s'.\n", dirin);
        return 1;
    }

    while ((entry = readdir(d)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0)
            continue;

        filenames = (char **)realloc(filenames, (nfiles + 1) * sizeof(char *));
        filenames[nfiles] = strdup(entry->d_name);
        nfiles++;
    }

    closedir(d);

    if (nfiles == 0) {
        fprintf(stderr, "No image files found in the input directory.\n");
        return 1;
    }

    // Build the main viewer HTML
    char mainhtmlpath[1024];
    snprintf(mainhtmlpath, sizeof(mainhtmlpath), "%s/%s.html", dirout, rootname);

    FILE *mainhtml = fopen(mainhtmlpath, "w");
    if (!mainhtml) {
        fprintf(stderr, "Failed to create main HTML file '%s'.\n", mainhtmlpath);
        return 1;
    }

    fprintf(mainhtml, "<html><head><title>%s</title></head><body>\n", rootname);
    fprintf(mainhtml, "<h1>%s</h1>\n<ul>\n", rootname);

    // Generate thumbnails and viewable images, and write links to HTML
    for (i = 0; i < nfiles; i++) {
        char fullpath[1024], thumbpath[1024], viewpath[1024];
        snprintf(fullpath, sizeof(fullpath), "%s/%s", dirin, filenames[i]);

        // Generate thumbnail and view image (example code assumes these functions exist)
        // These are placeholder calls; replace with actual image processing code
        generateThumbnail(fullpath, thumbpath, thumbwidth);
        generateViewImage(fullpath, viewpath, viewwidth);

        // Write thumbnail and link to HTML
        fprintf(mainhtml, "<li><img src='%s' width='%d'/><a href='%s'>%s</a></li>\n", 
                thumbpath, thumbwidth, viewpath, filenames[i]);
    }

    fprintf(mainhtml, "</ul></body></html>\n");
    fclose(mainhtml);

    // Free memory
    for (i = 0; i < nfiles; i++) {
        free(filenames[i]);
    }
    free(filenames);

    return 0;
}

