l_int32 generateHtmlImageGallery(const char *dirin, const char *dirout, const char *rootname, l_int32 thumbwidth, l_int32 viewwidth) {
    if (!dirin || !dirout || !rootname) {
        fprintf(stderr, "Invalid input parameters.\n");
        return 1;
    }

    // Create output directory if it doesn't exist
    struct stat st = {0};
    if (stat(dirout, &st) == -1) {
        if (mkdir(dirout, 0777) == -1) {
            perror("Failed to create output directory");
            return 1;
        }
    }

    // Open input directory
    DIR *dir = opendir(dirin);
    if (!dir) {
        perror("Failed to open input directory");
        return 1;
    }

    struct dirent *entry;
    char *thumbfile = NULL;
    char *viewfile = NULL;
    char *htmlmain = NULL;
    char *htmlthumbs = NULL;

    // Allocate memory for HTML content
    size_t htmlmain_len = 0;
    size_t htmlthumbs_len = 0;

    htmlmain = (char *)malloc(1024);
    if (!htmlmain) {
        perror("Memory allocation failed");
        closedir(dir);
        return 1;
    }
    htmlthumbs = (char *)malloc(1024);
    if (!htmlthumbs) {
        perror("Memory allocation failed");
        free(htmlmain);
        closedir(dir);
        return 1;
    }

    // Build HTML headers
    snprintf(htmlmain, 1024, "<html><body><h1>%s</h1><div id=\"main-view\"></div></body></html>", rootname);
    snprintf(htmlthumbs, 1024, "<html><body><h1>%s</h1><div id=\"thumbnails\"></div></body></html>", rootname);

    // Process image files in the input directory
    while ((entry = readdir(dir)) != NULL) {
        if (entry->d_type == DT_REG) {
            char *filename = entry->d_name;
            char *ext = strrchr(filename, '.');

            // Check if it's an image file (e.g., .jpg, .png, etc.)
            if (ext && (strcmp(ext, ".jpg") == 0 || strcmp(ext, ".png") == 0 || strcmp(ext, ".gif") == 0)) {
                // Generate thumbnail and viewable image (placeholder for actual image processing)
                // In a real implementation, you would generate or resize the images here.

                char thumbpath[1024];
                char viewpath[1024];
                char thumbhtml[1024];
                char viewhtml[1024];

                // Build paths for thumbnail and view image
                snprintf(thumbpath, sizeof(thumbpath), "%s/%s_thumb.%s", dirout, rootname, ext);
                snprintf(viewpath, sizeof(viewpath), "%s/%s_view.%s", dirout, rootname, ext);

                // Simulate thumbnail and view image creation
                // Actual implementation would generate these images from the source
                FILE *thumbfile = fopen(thumbpath, "w");
                if (!thumbfile) {
                    perror("Failed to create thumbnail image");
                    continue;
                }
                fclose(thumbfile);

                FILE *viewfile = fopen(viewpath, "w");
                if (!viewfile) {
                    perror("Failed to create view image");
                    continue;
                }
                fclose(viewfile);

                // Build HTML content for thumbnail and main view
                snprintf(thumbhtml, sizeof(thumbhtml), "<img src=\"%s\" width=\"%d\">", thumbpath, thumbwidth);
                snprintf(viewhtml, sizeof(viewhtml), "<img src=\"%s\" width=\"%d\">", viewpath, viewwidth);

                // Append to HTML content
                size_t new_len = htmlthumbs_len + strlen(thumbhtml) + 1;
                htmlthumbs = (char *)realloc(htmlthumbs, new_len);
                if (!htmlthumbs) {
                    perror("Memory allocation failed");
                    free(htmlmain);
                    closedir(dir);
                    return 1;
                }
                strcat(htmlthumbs, thumbhtml);

                new_len = htmlmain_len + strlen(viewhtml) + 1;
                htmlmain = (char *)realloc(htmlmain, new_len);
                if (!htmlmain) {
                    perror("Memory allocation failed");
                    free(htmlthumbs);
                    free(htmlmain);
                    closedir(dir);
                    return 1;
                }
                strcat(htmlmain, viewhtml);

                htmlthumbs_len = strlen(htmlthumbs);
                htmlmain_len = strlen(htmlmain);
            }
        }
    }

    closedir(dir);

    // Write HTML files
    char mainhtmlpath[1024];
    char thumbshtmlpath[1024];

    snprintf(mainhtmlpath, sizeof(mainhtmlpath), "%s/%s.html", dirout, rootname);
    FILE *mainhtml = fopen(mainhtmlpath, "w");
    if (!mainhtml) {
        perror("Failed to create main HTML file");
        free(htmlthumbs);
        free(htmlmain);
        return 1;
    }
    fprintf(mainhtml, "%s", htmlmain);
    fclose(mainhtml);

    snprintf(thumbshtmlpath, sizeof(thumbshtmlpath), "%s/%s_thumbs.html", dirout, rootname);
    FILE *thumbshtml = fopen(thumbshtmlpath, "w");
    if (!thumbshtml) {
        perror("Failed to create thumbnail HTML file");
        free(htmlthumbs);
        free(htmlmain);
        return 1;
    }
    fprintf(thumbshtml, "%s", htmlthumbs);
    fclose(thumbshtml);

    // Free memory
    free(htmlthumbs);
    free(htmlmain);

    return 0;
}

