l_int32 generateHtmlImageViewer(const char *dirin, const char *dirout, const char *rootname, l_int32 thumbwidth, l_int32 viewwidth) {
    if (!dirin || !dirout || !rootname) {
        fprintf(stderr, "Invalid input parameters.\n");
        return 1;
    }

    // Create output directory if it doesn't exist
    struct stat st = {0};
    if (stat(dirout, &st) == -1) {
        if (mkdir(dirout, 0777) == -1) {
            fprintf(stderr, "Failed to create output directory.\n");
            return 2;
        }
    }

    // Open input directory
    DIR *dp = opendir(dirin);
    if (!dp) {
        fprintf(stderr, "Failed to open input directory.\n");
        return 3;
    }

    // Read image filenames
    struct dirent *entry;
    char **imageFilenames = NULL;
    l_int32 count = 0;
    while ((entry = readdir(dp)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) {
            continue;
        }

        char *filename = (char *)malloc(strlen(entry->d_name) + 1);
        if (!filename) {
            fprintf(stderr, "Memory allocation failed.\n");
            closedir(dp);
            return 4;
        }

        strcpy(filename, entry->d_name);
        imageFilenames = (char **)realloc(imageFilenames, (count + 1) * sizeof(char *));
        imageFilenames[count++] = filename;
    }

    closedir(dp);

    if (count == 0) {
        fprintf(stderr, "No image files found in the input directory.\n");
        return 5;
    }

    // Generate thumbnail and viewable images
    for (l_int32 i = 0; i < count; i++) {
        char inputPath[1024];
        char thumbPath[1024];
        char viewPath[1024];

        snprintf(inputPath, sizeof(inputPath), "%s/%s", dirin, imageFilenames[i]);
        snprintf(thumbPath, sizeof(thumbPath), "%s/%s_thumb.jpg", dirout, imageFilenames[i]);
        snprintf(viewPath, sizeof(viewPath), "%s/%s_view.jpg", dirout, imageFilenames[i]);

        // Generate thumbnail
        l_int32 result = generateThumbnail(inputPath, thumbPath, thumbwidth);
        if (result != 0) {
            fprintf(stderr, "Failed to generate thumbnail for %s.\n", imageFilenames[i]);
            // Handle error or continue based on requirements
        }

        // Generate viewable image
        result = generateViewImage(inputPath, viewPath, viewwidth);
        if (result != 0) {
            fprintf(stderr, "Failed to generate viewable image for %s.\n", imageFilenames[i]);
            // Handle error or continue based on requirements
        }
    }

    // Create HTML files
    char mainHtmlPath[1024];
    char linksHtmlPath[1024];

    snprintf(mainHtmlPath, sizeof(mainHtmlPath), "%s/%s.html", dirout, rootname);
    snprintf(linksHtmlPath, sizeof(linksHtmlPath), "%s/%s_links.html", dirout, rootname);

    FILE *mainHtmlFile = fopen(mainHtmlPath, "w");
    if (!mainHtmlFile) {
        fprintf(stderr, "Failed to create main HTML file.\n");
        // Handle error or continue based on requirements
    }

    FILE *linksHtmlFile = fopen(linksHtmlPath, "w");
    if (!linksHtmlFile) {
        fprintf(stderr, "Failed to create links HTML file.\n");
        // Handle error or continue based on requirements
    }

    // Write HTML content for main viewer
    fprintf(mainHtmlFile, "<!DOCTYPE html>\n");
    fprintf(mainHtmlFile, "<html>\n");
    fprintf(mainHtmlFile, "<head>\n");
    fprintf(mainHtmlFile, "<title>Image Viewer</title>\n");
    fprintf(mainHtmlFile, "</head>\n");
    fprintf(mainHtmlFile, "<body>\n");

    for (l_int32 i = 0; i < count; i++) {
        char thumbPath[1024];
        snprintf(thumbPath, sizeof(thumbPath), "%s/%s_thumb.jpg", dirout, imageFilenames[i]);
        fprintf(mainHtmlFile, "<img src=\"%s\" alt=\"Thumbnail\" width=\"%d\" />\n", thumbPath, thumbwidth);
    }

    fprintf(mainHtmlFile, "</body>\n");
    fprintf(mainHtmlFile, "</html>\n");
    fclose(mainHtmlFile);

    // Write HTML content for links
    fprintf(linksHtmlFile, "<!DOCTYPE html>\n");
    fprintf(linksHtmlFile, "<html>\n");
    fprintf(linksHtmlFile, "<head>\n");
    fprintf(linksHtmlFile, "<title>Image Links</title>\n");
    fprintf(linksHtmlFile, "</head>\n");
    fprintf(linksHtmlFile, "<body>\n");

    for (l_int32 i = 0; i < count; i++) {
        char viewPath[1024];
        snprintf(viewPath, sizeof(viewPath), "%s/%s_view.jpg", dirout, imageFilenames[i]);
        fprintf(linksHtmlFile, "<a href=\"%s\">View %s</a><br />\n", viewPath, imageFilenames[i]);
    }

    fprintf(linksHtmlFile, "</body>\n");
    fprintf(linksHtmlFile, "</html>\n");
    fclose(linksHtmlFile);

    // Free memory
    for (l_int32 i = 0; i < count; i++) {
        free(imageFilenames[i]);
    }
    free(imageFilenames);

    return 0;
